import json
rules = []
def sq(r, f): return r*8+f
def rc(i): return divmod(i, 8)
def onb(r, f): return 0 <= r < 8 and 0 <= f < 8

def build(cons, newvals):
    pat, rep = [], []
    g = 0; run = 0; gi = {}
    def flush():
        nonlocal run, g
        if run:
            g += 1; pat.append('(.{%d})' % run); rep.append('\\g<%d>' % g); run = 0
    order = []
    for i in range(64):
        if i in cons:
            flush(); g += 1; gi[i] = g; pat.append('(' + cons[i] + ')'); order.append((len(rep), i)); rep.append(None)
        else:
            run += 1
    flush()
    for pos, i in order:
        v = newvals.get(i)
        if v is None: rep[pos] = '\\g<%d>' % gi[i]
        elif v.startswith('G'): rep[pos] = '\\g<%d>' % gi[int(v[1:])]
        else: rep[pos] = v
    return ''.join(pat), ''.join(rep), g

def gen(cons, newvals, ep='-', cast=r'\S+'):
    bp, br, g = build(cons, newvals)
    pat = r'\A@' + bp + r' (' + cast + r') (\S+)'
    rep = r'\g<0>' + '\n:' + br + r' \g<%d> ' % (g+1) + ep
    rules.append([pat, rep])

# --- parse input
rules.append([r'^(\S+) w (\S+) (\S+) .*$', r'@\1 \2 \3'])
for d in range(8, 0, -1):
    rules.append([str(d) + r'(?=[^ ]* )', '.' * d])
rules.append([r'/', ''])

files = 'abcdefgh'
# --- sliders, king, knight
ORTH = [(0,1),(0,-1),(1,0),(-1,0)]
DIAG = [(1,1),(1,-1),(-1,1),(-1,-1)]
KN = [(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]
for f in range(64):
    r0, f0 = rc(f)
    for dirs, cls in ((ORTH, '[RQ]'), (DIAG, '[BQ]')):
        for dr, df in dirs:
            path = []
            r, c = r0+dr, f0+df
            while onb(r, c):
                t = sq(r, c)
                cons = {f: cls, t: '[^A-Z]'}
                for p in path: cons[p] = r'\.'
                gen(cons, {f: '.', t: 'G%d' % f})
                path.append(t); r += dr; c += df
    for dr, df in ORTH + DIAG:
        if onb(r0+dr, f0+df):
            t = sq(r0+dr, f0+df)
            gen({f: 'K', t: '[^A-Z]'}, {f: '.', t: 'K'})
    for dr, df in KN:
        if onb(r0+dr, f0+df):
            t = sq(r0+dr, f0+df)
            gen({f: 'N', t: '[^A-Z]'}, {f: '.', t: 'N'})
# --- pawns
for r0 in range(1, 7):
    for f0 in range(8):
        f = sq(r0, f0); t = f - 8
        np = 'Q' if r0 == 1 else 'P'
        gen({f: 'P', t: r'\.'}, {f: '.', t: np})
        for df in (-1, 1):
            if 0 <= f0+df < 8:
                t = f - 8 + df
                gen({f: 'P', t: '[a-z]'}, {f: '.', t: np})
        if r0 == 6:
            gen({f: 'P', f-8: r'\.', f-16: r'\.'}, {f: '.', f-16: 'P'}, ep=files[f0] + '3')
# en passant
for ef in range(8):
    for df in (-1, 1):
        if 0 <= ef+df < 8:
            frm = sq(3, ef+df); cap = sq(3, ef); t = sq(2, ef)
            bp, br, g = build({frm: 'P', cap: 'p', t: r'\.'}, {frm: '.', cap: '.', t: 'P'})
            rules.append([r'\A@' + bp + r' (\S+) ' + files[ef] + '6', r'\g<0>' + '\n:' + br + r' \g<%d> -' % (g+1)])
# castling
rules.append([r'\A@(.{60})K\.\.R (\S*K\S*) (\S+)', r'\g<0>' + '\n:' + r'\1XXK. \2 -'])
rules.append([r'\A@(.{56})R\.\.\.K(.{3}) (\S*Q\S*) (\S+)', r'\g<0>' + '\n:' + r'\1..KXX\2 \3 -'])

# --- check filter
def cpat(cons):
    s = []; run = 0
    for i in range(64):
        if i in cons:
            if run: s.append('.{%d}' % run); run = 0
            s.append(cons[i])
        else: run += 1
    return ''.join(s)
def kill(cons):
    rules.append([r'\n:' + cpat(cons) + r'[^\n]*', ''])
T = '[KX]'
for k in range(64):
    r0, f0 = rc(k)
    for dirs, cls in ((ORTH, '[rq]'), (DIAG, '[bq]')):
        for dr, df in dirs:
            path = []
            r, c = r0+dr, f0+df
            while onb(r, c):
                a = sq(r, c)
                cons = {k: T, a: cls}
                for p in path: cons[p] = r'\.'
                kill(cons)
                path.append(a); r += dr; c += df
    for dr, df in ORTH + DIAG:
        if onb(r0+dr, f0+df): kill({k: T, sq(r0+dr, f0+df): 'k'})
    for dr, df in KN:
        if onb(r0+dr, f0+df): kill({k: T, sq(r0+dr, f0+df): 'n'})
    for df in (-1, 1):
        if onb(r0-1, f0+df): kill({k: T, sq(r0-1, f0+df): 'p'})

# --- finalize castling ghosts
rules.append([r'XXK', '.RK'])
rules.append([r'KXX', 'KR.'])
# castling rights
def cr(idx, ch, letter):
    rules.append([r'(?m)^(:' + ('.{%d}' % idx if idx else '') + '[^' + ch + ']' + ('.{%d}' % (63-idx) if idx < 63 else '') + r' [^ ' + letter + ']*)' + letter, r'\1'])
cr(60, 'K', 'K'); cr(60, 'K', 'Q'); cr(63, 'R', 'K'); cr(56, 'R', 'Q')
cr(4, 'k', 'k'); cr(4, 'k', 'q'); cr(7, 'r', 'k'); cr(0, 'r', 'q')
rules.append([r'(?m)^(:.{64})  ', r'\1 - '])
# drop original
rules.append([r'\A@[^\n]*\n?', ''])
rules.append([r'(?m)^:' + '(.{8})' * 8 + r' (\S+) (\S+)$', '/'.join(r'\g<%d>' % i for i in range(1, 9)) + r' b \g<9> \g<10> 0 0'])
for d in range(8, 0, -1):
    rules.append(['\\.' * d, str(d)])
json.dump(rules, open('/tmp/obench-cell-hxjzf05s/bench_opencode_regex-chess_njcmuk_q/re.json', 'w'))
print(len(rules))
